int path_to_user(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;

    while (i < fromlen) {
        int namelen = from[i];

        if (namelen == 0)
            i += 2;
        else if (namelen == 1 && j == 0)
            i += 2;
        else {
            if (j + namelen >= tolen)
                return -ENAMETOOLONG;

            memcpy(to + j, from + i + 1, namelen);
            j += namelen;
            if (j < tolen)
                to[j++] = '/';
            if (j >= tolen)
                return -ENAMETOOLONG;
        }
        i += 2 + namelen;
    }

    if (j > 0)
        j--;

    if (j + 1 >= tolen)
        return -ENAMETOOLONG;

    to[j] = '\0';

    return 0;
}

int convert_path_component(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int res = 0;
    unsigned char *src = from;
    unsigned char *dst = to;
    unsigned char *end = to + tolen;

    while (fromlen > 0) {
        if (dst >= end - 1) {
            return -ENAMETOOLONG;
        }

        if (*src == '/') {
            if (dst == to || *(dst - 1) != '/') {
                *dst++ = '/';
            }
        } else if (*src == '\0') {
            *dst++ = '.';
        } else {
            *dst++ = *src;
        }

        src++;
        fromlen--;
    }

    if (dst >= end) {
        return -ENAMETOOLONG;
    }

    *dst = '\0';
    return res;
}

int from_path(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int res = 0;
    int offset = 0;
    int i = 0;

    while (i < fromlen) {
        if (offset >= tolen - 1)
            return -ENAMETOOLONG;

        if (from[i] == FILE_NAME) {
            int namelen = from[i + 1];
            if (i + 2 + namelen > fromlen)
                return -EIO;

            if (offset + namelen >= tolen - 1)
                return -ENAMETOOLONG;

            memcpy(&to[offset], &from[i + 2], namelen);
            offset += namelen;
            i += 2 + namelen;
        } else if (from[i] == DIR_NAME) {
            to[offset] = '/';
            offset++;
            i++;
        } else if (from[i] == SYMLINK_NAME) {
            if (i + 1 > fromlen)
                return -EIO;

            int symlinklen = from[i + 1];
            if (i + 2 + symlinklen > fromlen)
                return -EIO;

            if (offset + symlinklen >= tolen - 1)
                return -ENAMETOOLONG;

            memcpy(&to[offset], &from[i + 2], symlinklen);
            offset += symlinklen;
            i += 2 + symlinklen;
        } else {
            return -EIO;
        }
    }

    to[offset] = '\0';
    return 0;
}

int nameidata_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int pos = 0;
    int i = 0;

    while (i < fromlen && pos < tolen - 1) {
        int namelen = from[i];

        if (namelen == 0) {
            i += 1;
            continue;
        }

        if (i + namelen > fromlen) {
            return -EIO;
        }

        if (pos + namelen + 1 > tolen) {
            return -ENAMETOOLONG;
        }

        memcpy(&to[pos], &from[i + 1], namelen);
        pos += namelen;
        to[pos] = '/';

        i += namelen + 1;
    }

    if (pos > 0) {
        pos -= 1;
    }

    to[pos] = '\0';

    return 0;
}
